insert into bev_dataset (dataset_version, key, value, unit, status, publisher, published_on, source_url, note) values
  ('v-2026-10-03-0003', 'rate.home', 0.265, 'CHF/kWh', 'sourced', 'ElCom via the Federal Council, press release on 2027 electricity tariffs', '2026-09-08', 'https://www.admin.ch/de/newnsb/1miE201yRzoA', 'National median 2027, profile H4 (4,500 kWh a year): 26.5 Rp./kWh. 2026 was 27.7. TCS Kilometerkosten 2026 (6 Jan 2026) used 28 rappen. Replaced by the ElCom canton or commune figure when one is picked.'),
  ('v-2026-10-03-0003', 'rate.homeSpecial', 0.21, 'CHF/kWh', 'placeholder', null, null, null, 'Home electricity on an off-peak or electric-car tariff. Illustrative.'),
  ('v-2026-10-03-0003', 'rate.work', 0.18, 'CHF/kWh', 'placeholder', null, null, null, 'Illustrative staff rate at work. Not free electricity.'),
  ('v-2026-10-03-0003', 'rate.public', 0.59, 'CHF/kWh', 'placeholder', null, null, null, 'TCS 2026 (page undated): DC average 59 Rp./kWh, AC average 50. The model uses the DC average. Prices differ by half or more between providers.'),
  ('v-2026-10-03-0003', 'rate.publicPlan', 0.51, 'CHF/kWh', 'placeholder', null, null, null, 'TCS 2026 (page undated): DC with a subscription 51 Rp./kWh, AC budget 40. The model uses the DC subscription figure.'),
  ('v-2026-10-03-0003', 'rate.pv', 0.06, 'CHF/kWh', 'placeholder', null, null, null, 'Own solar power, opportunity cost.'),
  ('v-2026-10-03-0003', 'rate.pvShare', 0.4, 'share', 'placeholder', null, null, null, 'Share of home kilometres charged from own solar when the switch is on.'),
  ('v-2026-10-03-0003', 'rate.rentalDay', 75, 'CHF/day', 'placeholder', null, null, null, 'Day rate for a larger rental car. Not a rental company.'),
  ('v-2026-10-03-0003', 'rate.wallbox', 2200, 'CHF', 'placeholder', null, null, null, 'Observed range 900 to 2,500 CHF for one wallbox (Beobachter, undated). Up to 15,000 CHF for an 18-bay building.'),
  ('v-2026-10-03-0003', 'rate.sharedInstall', 1500, 'CHF', 'placeholder', null, null, null, 'Unverified. Reported cases run up to 15,000 CHF for an 18-bay building (Beobachter, undated).'),
  ('v-2026-10-03-0003', 'rate.batteryCheck', 250, 'CHF', 'placeholder', null, null, null, 'Battery-health check on a used car.'),
  ('v-2026-10-03-0003', 'rate.horizon', 8, 'years', 'sourced', 'EnergieSchweiz, Swiss Federal Office of Energy', '2023-03-23', 'https://www.newsd.admin.ch/newsd/message/attachments/76353.pdf', 'Window of the picture.'),
  ('v-2026-10-03-0003', 'pump.petrol', 1.83, 'CHF/litre', 'sourced', 'TCS (Touring Club Schweiz), Benzinpreise Schweiz', '2026-09-19', 'https://www.tcs.ch/de/camping-reisen/reiseinformationen/wissenswertes/fahrkosten-gebuehren/benzinpreise-schweiz.php', 'Euro-Super 95. Derived: the time-weighted average of the 23 entries in the TCS table from 1 Jan to 19 Sep 2026 (261 days), each price counted from its date to the next entry. The latest single price, 19 Sep, is 2.14, the highest of the year; the lowest is 1.61 (3 Feb). TCS Kilometerkosten 2026 (6 Jan 2026) used 1.71 as a yearly average. Replaced by a federal monthly average if one is wired.'),
  ('v-2026-10-03-0003', 'pump.diesel', 2.03, 'CHF/litre', 'sourced', 'TCS (Touring Club Schweiz), Benzinpreise Schweiz', '2026-09-19', 'https://www.tcs.ch/de/camping-reisen/reiseinformationen/wissenswertes/fahrkosten-gebuehren/benzinpreise-schweiz.php', 'Diesel. Derived: the time-weighted average of the 23 entries in the TCS table from 1 Jan to 19 Sep 2026 (261 days), each price counted from its date to the next entry. The latest single price, 19 Sep, is 2.46, the highest of the year; the lowest is 1.73 (3 Feb). Replaced by a federal monthly average if one is wired.'),
  ('v-2026-10-03-0003', 'pump.hybrid', 1.83, 'CHF/litre', 'placeholder', null, null, null, 'Equals pump.petrol. A hybrid buys petrol: the model reads pump.petrol for it and ignores this row.'),
  ('v-2026-10-03-0003', 'spec.small.iceL', 5.4, 'l/100km', 'placeholder', null, null, null, 'Class placeholder, not a quote. For scale: TCS Kilometerkosten 2026 (6 Jan 2026) uses 5 l/100 km for one model car. The federal average of all new cars in 2025 is 5.1 l petrol-equivalent, but it includes electrified cars, so it is not a petrol class figure (BFE, 23 Jun 2026).'),
  ('v-2026-10-03-0003', 'spec.small.iceIns', 740, 'CHF/year', 'placeholder', null, null, null, 'Class placeholder, not a quote. Comparis (19 Aug 2025): fully comprehensive cover is cheaper for an electric car in 70 % of cases. Many insurers expected higher premiums in 2026.'),
  ('v-2026-10-03-0003', 'spec.small.iceTax', 190, 'CHF/year', 'placeholder', null, null, null, 'Class placeholder, not a quote.'),
  ('v-2026-10-03-0003', 'spec.small.iceMaint', 780, 'CHF/year', 'placeholder', null, null, null, 'Class placeholder, not a quote.'),
  ('v-2026-10-03-0003', 'spec.small.resale', 4800, 'CHF', 'placeholder', null, null, null, 'Class placeholder. No public Swiss resale figure by class was found. Used electric listings in 2025 were about 3 % below 2020 levels (AutoScout24, 13 Jan 2026), which says nothing by class. Needs a Eurotax or AutoScout24 extract.'),
  ('v-2026-10-03-0003', 'spec.small.bevNew', 27900, 'CHF', 'placeholder', null, null, null, 'Class placeholder. Swiss average listing price of a new electric car: 51,424 CHF in Q1 2026, down 4.2 % (AutoScout24, 9 Apr 2026). The 2025 full-year average was 56,229 CHF, down 8.1 % (AutoScout24, 13 Jan 2026). Not comparable by class.'),
  ('v-2026-10-03-0003', 'spec.small.bevUsed', 16800, 'CHF', 'placeholder', null, null, null, 'Class placeholder. Swiss average listing price of a used electric car: 40,599 CHF in Q1 2026, down 3.2 % (AutoScout24, 9 Apr 2026). The 2025 full-year average was 43,549 CHF, down 8.3 % (AutoScout24, 13 Jan 2026). Skewed by expensive models.'),
  ('v-2026-10-03-0003', 'spec.small.kwh', 14.2, 'kWh/100km', 'placeholder', null, null, null, 'Class placeholder, not a quote. For scale: TCS Kilometerkosten 2026 (6 Jan 2026) uses 18 kWh/100 km for one model car. The TCS winter test of 26 Jan 2026 (about 0 °C) measured 22.2 (Tesla Model Y) to 31.6 (Volvo EX90). The EnergieSchweiz label shows 13 to 30.6 across models (Oct 2023).'),
  ('v-2026-10-03-0003', 'spec.small.battery', 40, 'kWh', 'placeholder', null, null, null, 'Usable battery, class placeholder. Used only for the ordinary-week strip, never for francs.'),
